def svg(key):
 from clinic_illustrations_v4 import svg as refined_svg
 refined=refined_svg(key)
 if refined:return refined
 if key in SCENES:
  return '<svg class="ls-illustration" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 120 96" width="120" height="96" fill="none" stroke="#76543d" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">'+SCENES[key]+'</svg>'
 return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" width="64" height="64" fill="none" stroke="currentColor" stroke-width="1.45" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">'+''.join('<path d="'+p+'"/>' for p in P[key])+'</svg>'
if __name__=='__main__':
 d=Path('output/services-editorial/icons');d.mkdir(exist_ok=True)
 for key in P:(d/(key+'.svg')).write_text(svg(key),encoding='utf-8')
 Path('output/site-preview/services/icon-prototypes.html').write_text('<!doctype html><meta charset="utf-8"><style>body{background:#fcfbf8;color:#8b7058;display:flex;gap:64px;padding:64px;font:18px sans-serif}div{text-align:center}svg{width:128px;height:128px;display:block;margin-bottom:24px}</style>'+''.join('<div>'+svg(k)+k+'</div>' for k in P),encoding='utf-8')
